static int c4iw_uld_control ( void * handle , enum cxgb4_control control , ... ) { struct uld_ctx * ctx = handle ; switch ( control ) { case CXGB4_CONTROL_DB_FULL : stop_queues ( ctx ) ; ctx -> dev -> rdev . stats . db_full ++ ; break ; case CXGB4_CONTROL_DB_EMPTY : resume_queues ( ctx , NULL ) ; mutex_lock ( & ctx -> dev -> rdev . stats . lock ) ; ctx -> dev -> rdev . stats . db_empty ++ ; mutex_unlock ( & ctx -> dev -> rdev . stats . lock ) ; break ; case CXGB4_CONTROL_DB_DROP : recover_queues ( ctx ) ; mutex_lock ( & ctx -> dev -> rdev . stats . lock ) ; ctx -> dev -> rdev . stats . db_drop ++ ; mutex_unlock ( & ctx -> dev -> rdev . stats . lock ) ; break ; default : pr_warn ( "%s: unknown control cmd %u\n" , pci_name ( ctx -> lldi . pdev ) , control ) ; break ; } return 0 ; } 